package edu.facilities.service;
import edu.facilities.model.*; import java.sql.*; import java.time.*; import java.util.*;
public class MaintenanceService {
 public long createTicket(String roomId,String description,User reporter)throws SQLException{if(description==null||description.isBlank())throw new IllegalArgumentException("Issue description is required.");try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement("insert into maintenance_tickets(room_id,reporter_id,description) values(?,?,?) returning id")){s.setLong(1,Long.parseLong(roomId));s.setLong(2,Long.parseLong(reporter.getId()));s.setString(3,description.trim());try(ResultSet r=s.executeQuery()){if(r.next())return r.getLong(1);}}return -1;}
 public List<MaintenanceTicket> getTickets(User u)throws SQLException{String sql="select t.id,t.description,t.status,t.created_at,r.id rid,r.room_code,r.name,r.type,r.capacity,r.location,r.status rstatus,u.id uid,u.username,u.role from maintenance_tickets t join rooms r on r.id=t.room_id join users u on u.id=t.reporter_id where (?='ADMIN' or t.reporter_id=? or t.assigned_to=?) order by t.created_at desc";List<MaintenanceTicket> out=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){s.setString(1,u.getUserType());s.setLong(2,Long.parseLong(u.getId()));s.setLong(3,Long.parseLong(u.getId()));try(ResultSet x=s.executeQuery()){while(x.next()){Room room=new Room(String.valueOf(x.getLong("rid")),x.getString("room_code"),RoomType.valueOf(x.getString("type")),x.getInt("capacity"),x.getString("location"),RoomStatus.valueOf(x.getString("rstatus")));User reporter=new Student(String.valueOf(x.getLong("uid")),x.getString("username"),null);out.add(new MaintenanceTicket(String.valueOf(x.getLong("id")),room,reporter,null,x.getString("description"),TicketStatus.valueOf(x.getString("status")),x.getTimestamp("created_at").toLocalDateTime(),null));}}}return out;}
 public void assign(long ticketId,long staffId)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement("update maintenance_tickets set assigned_to=?,status='ASSIGNED' where id=?")){s.setLong(1,staffId);s.setLong(2,ticketId);if(s.executeUpdate()==0)throw new SQLException("Ticket not found");}}
 public void updateStatus(long ticketId,TicketStatus status)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement("update maintenance_tickets set status=? where id=?")){s.setString(1,status.name());s.setLong(2,ticketId);s.executeUpdate();}}
}
